EVENTS += "\nquest_keepers={}\nlocal a=DH2CreatePropertyState(2);a:SetProp(79,1280);a:SetProp(80,1280);a:SetProp(97,-256);a:SetCombatContext(0,0,'attacker')\nfor k=0,3 do quest_keepers[k+1]=DH2CreateKillObjective{kind=k,match_id=k<2 and 5 or 7,current=0,required=2,completed=false}end\nfor kill=1,3 do\n damage_keeper:SetDeathContext(death_ctx);damage_keeper:SetHP(10);hit_policy.target_dead=false\n CF_ClearCombatants();CF_SetCombatants(a,damage_keeper,-1,false,false);DH2SeedRandom(0)\n local raw=CF_CalcDamage(0,0)\n assert(raw==1280)\n local p,d=damage_keeper:ApplyNonplayerHit(raw,hit_policy,17);assert(p and not d and damage_keeper:GetHP()==5)\n p,d=damage_keeper:ApplyNonplayerHit(raw,hit_policy,17);assert(p and d and damage_keeper:GetHP()==0)\n local dead=damage_keeper:KillNonplayer(death_policy);assert(dead.processed and #dead.events==4)\n for _,q in ipairs(quest_keepers)do for _,e in ipairs(dead.events)do\n  local r=q:ConsumeKillEvent(e)\n  if r.matched then assert(r.changed and r.progress.current==kill and r.event.quantity==kill and r.event.outbound)\n   assert(r.completion_requested==(kill>=2) and r.newly_completed==(kill==2))end\n end;local v=q:GetProgress();assert(v.current==kill and v.completed==(kill>=2))end\n assert(#damage_keeper:KillNonplayer(death_policy).events==0)\nend\nCF_ClearCombatants()\nquest_sync={kind=0,match_id=5,synchronized=true,quantity=2,outbound=false}\nlocal q=quest_keepers[1];local r=q:ConsumeKillEvent(quest_sync);assert(r.matched and not r.changed and r.progress.current==3)\nquest_sync.quantity=8;r=q:ConsumeKillEvent(quest_sync);assert(r.changed and r.completion_requested and not r.newly_completed and r.progress.current==8 and not r.event.outbound)\nquest_sync.match_id=6;r=q:ConsumeKillEvent(quest_sync);assert(not r.matched and r.progress.current==8);quest_sync.match_id=5\nquest_sync.kind=1;r=q:ConsumeKillEvent(quest_sync);assert(not r.matched and q:GetProgress().current==8);quest_sync.kind=0\nfor _,v in ipairs({1.5,0/0,1/0,2147483648,'9'})do quest_sync.quantity=v;assert(not pcall(function()q:ConsumeKillEvent(quest_sync)end));assert(q:GetProgress().current==8)end\nquest_sync.quantity=9;quest_sync.synchronized=0;assert(not pcall(function()q:ConsumeKillEvent(quest_sync)end));assert(q:GetProgress().current==8)\nquest_sync.synchronized=true\nassert(not pcall(function()q:ConsumeKillEvent({})end));assert(not pcall(function()DH2CreateKillObjective{}end))\n"
